 entry=json.loads((w/f'window_{i:03}.json').read_text());v={'market_id':entry['item']['member']['market_id'],'question':entry['item']['identity']['question'],'missing_reason':entry['missing_reason'],'sources':[]}
 for rp in sorted((w/f'fs2_capture_screen_{i:03}').glob('*/receipt.json')):
  r=json.loads(rp.read_text());raw=rp.parent/'raw.bin';b=raw.read_bytes();j=json.loads(b);j=j[0] if isinstance(j,list) else j
  rec={'source_id':r['source_id'],'raw_path':str(raw),'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'receipt_path':str(rp),'receipt_sha256':hashlib.sha256(rp.read_bytes()).hexdigest(),'status':r['status']}
  if r['source_id']=='gamma.market':rec['fields']={k:j.get(k) for k in ['question','description','resolutionSource','active','closed','archived','acceptingOrders','endDate','events']}
  if r['source_id']=='clob.book':rec['fields']={'bid_levels':len(j.get('bids',[])) if 'bids' in j else None,'ask_levels':len(j.get('asks',[])) if 'asks' in j else None,'raw_timestamp':j.get('timestamp'),'error':j.get('error')}
  v['sources'].append(rec)
 v['family_review']={'external':'unavailable_no_pre_origin_rule_matched_source','nws_knyc':'not_applicable_to_quantity_in_rules','related_price':'unavailable_no_pre_origin_group_and_price_binding'}
 reviews.append(v)
e['availability_and_rule_review']=reviews
e['family_eligibility_review']={'external':'Complete retained rules reviewed for all8. Sports rules specify season statistics/match outcomes, not KNYC weather. Both Bitcoin markets specify the Binance BTC/USDT hourly close; an alternative exchange is not the stated quantity. No relevant source was bound before origin; resolution-source references do not establish access rights or source admission.', 'related':'Bitcoin thresholds share an instrument/candle cutoff rule, but no pre-origin relation/price feature is bound and both sampled books are unavailable. Different fantasy positions, teams and matches are not one complete outcome group. Shared words or sport do not establish economic independence.', 'flow_depth_persistence':'F01/F02/F10/F27 stay unavailable. Raw bounded taker records and receipt hold diagnostics do not prove complete fills, pre-trade ordering, execution-adjusted deltas or native continuity.', 'v1':'The pilot cannot reconstruct the absent v1 seven-component vector or rolling z-score. No v1 result is manufactured; locked scientific baselines remain Phase4.'}
e['reviewed_at']=datetime.now(timezone.utc).isoformat()
e['conclusion']='Frozen six-of-eight origin/history gates failed:5observed origins/5fresh histories/5valid targets. New observer-accounting and original audit gates passed. No redraw or retrospective acceptance.'
e['preservation_script']={'sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'source':Path(__file__).read_text()}
p.write_text(json.dumps(e,indent=2,sort_keys=True)+'\n')
print(json.dumps({'stratum_draw':e['stratum_draw'],'pairs':e['observed_matched_pairs'],'history_count':len(e['eligible_completed_window_history_markets']),'verified_artifacts':e['independent_artifact_check_count'],'timing':e['origin_timing'],'windows':[{'market':v['market_id'],'terminal':v['socket']['terminal'] if v['socket'] else None,'coverage':v['coverage']['reconstructed_receipt_duration_ns'] if v['coverage'] else None,'states':[i['state'] for i in v['coverage']['items']] if v['coverage'] else []} for v in e['window_summaries']]}))
